// "Prepare to reinstall" (memory-downgrade --to 10) must leave a file 1.0.2 opens. 1.0.2's validateMemorySchema refuses any memory_
// object it does not know (MEMORY_SCHEMA_UNSUPPORTED, so 1.0.2 cannot start) and requires every v10 object it does know. The objects it
// accepts are frozen in testing/schema-1.0.2-accepted.json, generated by running the 1.0.2 code itself (afbf549ba), so this compares the
// downgrade's result with 1.0.2's own rule, never with the current validator (which knows every 1.0.3 object).
import { readFileSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";
import { expect, it } from "vitest";
import { downgradeMemorySchema, migrateMemorySchema, OWNER_TAIL_SCHEMA } from "./schema.ts";
import { OPTIONAL_INDEXES } from "./optional-index.ts";
import "../transcript-seq.ts"; // registers the transcript index, so every optional index 1.0.3 makes is built below

type Row = { type: string; name: string; tbl_name: string; sql: string | null };
const frozen = JSON.parse(readFileSync(new URL("./testing/schema-1.0.2-accepted.json", import.meta.url), "utf8")) as { required: string[]; accepted: Row[] };
const accepted = new Map(frozen.accepted.map(row => [row.name, row]));

/** A 1.0.3 file with every object 1.0.3 makes: the v11 text, the late revoke objects (the fold map among them), the lane-2 derived
 *  objects, the owner tail and every registered optional index. */
function full103(): DatabaseSync {
  const db = new DatabaseSync(":memory:");
  db.exec("CREATE TABLE messages(thread_id TEXT NOT NULL,id TEXT NOT NULL,at INTEGER NOT NULL,role TEXT NOT NULL,kind TEXT NOT NULL,text TEXT,json TEXT NOT NULL,seq INTEGER,PRIMARY KEY(thread_id,id));");
  migrateMemorySchema(db);
  db.exec(OWNER_TAIL_SCHEMA);
  const table = db.prepare("SELECT 1 FROM sqlite_schema WHERE type='table' AND name=?");
  for (const index of OPTIONAL_INDEXES) if (table.get(index.table)) db.exec(index.sql);
  return db;
}
const memoryRows = (db: DatabaseSync) => (db.prepare("SELECT type,name,tbl_name,sql FROM sqlite_schema").all() as Row[])
  .filter(row => row.name.startsWith("memory_") || row.tbl_name.startsWith("memory_"));
/** What 1.0.2 would refuse: an object it does not know or whose text differs, and any required v10 object that is missing. */
function refusedBy102(db: DatabaseSync) {
  const rows = memoryRows(db);
  const unknown = rows.filter(row => { const want = accepted.get(row.name); return !want || want.type !== row.type || want.tbl_name !== row.tbl_name || want.sql !== row.sql; }).map(row => row.name).sort();
  const names = new Set(rows.map(row => row.name));
  const missing = frozen.required.filter(name => !names.has(name));
  return { unknown, missing };
}

it("the fixture is 1.0.2's list: it names no 1.0.3 object", () => {
  expect(accepted.has("memory_revoke_fold")).toBe(false);
  expect(accepted.has("memory_revoke_fold_bulk")).toBe(false);
  expect(accepted.has("memory_deny")).toBe(true);
  expect(frozen.required).toContain("memory_meta");
});

it("a full 1.0.3 file has objects 1.0.2 refuses before the downgrade (the check sees them)", () => {
  const db = full103();
  try {
    const { unknown } = refusedBy102(db);
    expect(unknown).toEqual(expect.arrayContaining(["memory_revoke_fold", "memory_revoke_fold_bulk", "memory_meta"]));
  } finally { db.close(); }
});

it("memory-downgrade --to 10 leaves exactly objects 1.0.2 accepts, every 1.0.3 addition gone and every v10 object kept", () => {
  const db = full103();
  try {
    expect(downgradeMemorySchema(db, 10)).toEqual({ status: "downgraded", from: 13, to: 10 });
    expect(refusedBy102(db)).toEqual({ unknown: [], missing: [] });
  } finally { db.close(); }
});

it("a file an earlier 1.0.3 downgrade left with the fold map still in it is finished by a second run", () => {
  const db = full103();
  try {
    downgradeMemorySchema(db, 10);
    db.exec("CREATE TABLE IF NOT EXISTS memory_revoke_fold (old_id INTEGER PRIMARY KEY NOT NULL, bulk_id INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS memory_revoke_fold_bulk ON memory_revoke_fold(bulk_id);");
    expect(downgradeMemorySchema(db, 10)).toEqual({ status: "downgraded", from: 10, to: 10 });
    expect(refusedBy102(db)).toEqual({ unknown: [], missing: [] });
    expect(downgradeMemorySchema(db, 10)).toMatchObject({ status: "already-v10" });
  } finally { db.close(); }
});
